mapper.select:
select ppa.project_attachment_id, ppa.project_id, ppa.project_attachment_category, ppa.document_name, ppa.description, ppa.signed_date, ppa.contract_number, (select nvl(count(faa.attachment_id),0) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_sum, (select max(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_id, (select wm_concat(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_id_n, (select wm_concat(faa.file_name) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) file_names, (select wm_concat(faa.source_pk_value) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) source_pk_value, (select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id ) file_name, (select max(fat.last_update_date) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id) upload_date, (select max(su.description) from sys_user su, fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and su.user_id = fat.last_updated_by) upload_person
from prj_project_attachment ppa where ppa.project_attachment_category = 'CONTRACT' and ppa.prj_project_type is null and ppa.project_id = #{projectId}
AND ppa.project_attachment_category != #{projectAttachmentCategory}

select ppa.project_id as funding_plan_id, ppa.project_attachment_id, ppa.project_id, ppa.project_attachment_category, ppa.document_name, ppa.description, (select nvl(count(faa.attachment_id),0) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_sum, (select max(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_id, (select wm_concat(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_id_n, (select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id ) file_name, (select max(fat.last_update_date) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id) upload_date, (select max(su.description) from sys_user su, fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and su.user_id = fat.last_updated_by) upload_person
from prj_project_attachment ppa where ppa.project_attachment_category = 'CON_CONTRACT_ATT' and ppa.project_id = #{projectId}
union
select ppa.project_id as funding_plan_id, ppa.project_attachment_id, ppa.project_id, ppa.project_attachment_category, ppa.document_name, ppa.description, (select nvl(count(faa.attachment_id),0) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_sum, (select max(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_id, (select wm_concat(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_id_n, (select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id ) file_name, (select max(fat.last_update_date) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id) upload_date, (select max(su.description) from sys_user su, fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and su.user_id = fat.last_updated_by) upload_person
from prj_project_attachment ppa where ppa.project_attachment_category = 'HLS_FUNDING_PLAN' and ppa.prj_project_type = 'HLS_FUNDING_PLAN' and ppa.project_id = #{fundingPlanId}

select ppa.project_attachment_id, ppa.project_id, ppa.project_attachment_category, ppa.document_name, ppa.description, (select nvl(count(faa.attachment_id),0) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_sum, (select max(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_id, (select wm_concat(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and faa.source_pk_value = faam.record_id) attachment_id_n,
(select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id ) file_name_pay, (select max(fat.last_update_date) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id) upload_date, (select max(su.description) from sys_user su, fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = ppa.project_attachment_id and su.user_id = fat.last_updated_by) upload_person
from prj_project_attachment ppa where ppa.project_attachment_category = 'CON_PAYMENT' and ppa.project_id = #{projectId}

SELECT ppa.project_id, ppa.project_attachment_id, ppa.document_name, ppa.description, ( select description from sys_user where user_id = ppa.last_updated_by ) upload_person, ppa.last_update_date upload_date, ppa.project_attachment_category FROM prj_project_attachment ppa
and ppa.project_id = #{projectId,jdbcType=BIGINT}
and ppa.project_attachment_category = #{projectAttachmentCategory,jdbcType=VARCHAR}

SELECT ppa.*
FROM prj_project_attachment ppa
WHERE ppa.project_id = #{projectId}
AND ppa.project_attachment_category = #{projectAttachmentCategory}

SELECT t1.document_name, sf.file_id, sf.file_name, sf.file_type, sf.upload_date, sf.file_size, t1.project_attachment_id, t1.project_attachment_category as source_type, t1.project_attachment_category, t1.project_id, t1.description, -- t1.wfl_upload, t1.company_seal, t1.rep_seal, t1.wfl_upload,t1.is_final_print,t1.copies,t1.stamp_name,t1.print_comment, (SELECT su.description FROM sys_user su WHERE su.user_id = sf.last_updated_by) uploadPerson FROM ( SELECT pa.document_name,pa.project_attachment_id,pa.project_id,pa.project_attachment_category, pa.description,pa.wfl_upload,pa.is_final_print,pa.copies,pa.stamp_name,pa.print_comment,pa.company_seal,pa.rep_seal, a.attachment_id FROM prj_project_attachment pa LEFT JOIN sys_attachment a on cast(a.SOURCE_KEY as char(500))=cast(pa.project_attachment_id as char(500)) AND a.source_type = pa.project_attachment_category WHERE 1=1
AND pa.project_attachment_category in
#{item}
AND pa.project_id = #{projectId}
AND pa.is_final_print = #{isFinalPrint}
) t1 LEFT JOIN sys_file sf ON sf.attachment_id = t1.attachment_id

SELECT hba.project_attachment_id, hba.document_name, ( SELECT wm_concat ( sf.file_name ) FROM sys_attachment sa, sys_file sf WHERE hba.project_attachment_id = sa.source_key AND sa.source_type = #{projectAttachmentCategory} AND sa.attachment_id = sf.attachment_id ) file_name, ( select wm_concat ( sf.file_id ) from sys_attachment sa, sys_file sf
hba.project_attachment_id||''= sa.source_key
AND sa.source_type = #{sourceType}
AND sa.attachment_id = sf.attachment_id
) file_id, hba.description, hba.project_attachment_category FROM prj_project_attachment hba WHERE hba.project_attachment_category = #{projectAttachmentCategory} AND hba.project_id = #{projectId} ORDER BY last_update_date ASC

SELECT hba.project_attachment_id, hba.document_name, ( SELECT wm_concat ( sf.file_name ) FROM sys_attachment sa, sys_file sf
hba.project_attachment_id = sa.source_key
AND sa.source_type = #{projectAttachmentCategory}
AND sa.attachment_id = sf.attachment_id
) file_name, hba.description FROM prj_project_attachment hba
1 = 1
AND hba.project_attachment_category = #{projectAttachmentCategory}
AND hba.project_id = #{projectId}
ORDER BY last_update_date ASC

select nvl(max(ppa.order_number),0)+1 order_number from prj_project_attachment ppa where 1=1
AND ppa.project_attachment_category = #{projectAttachmentCategory}
AND ppa.project_id = #{projectId}

SELECT
    pa.*,
    (select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id
      and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = pa.project_attachment_id
      ) file_name
FROM
    prj_project_attachment pa
WHERE
        pa.project_id = #{projectId}
    and pa.project_attachment_category = #{projectAttachmentCategory}

select tab.* from( SELECT t1.document_name, t1.file_id, sf.file_name, sf.file_type, sf.file_suffix, sf.upload_date, sf.file_size, sf.last_updated_by as upload_person_id, sf.file_path, (SELECT su.description FROM sys_user su WHERE su.user_id = sf.last_updated_by) uploadPerson FROM ( SELECT pa.document_name,pa.project_attachment_id,pa.project_id,pa.project_attachment_category,pa.attachment_code,pa.order_number,pa.creation_date, pa.source_id AS file_id,pa.description,pa.wfl_upload,pa.is_final_print,pa.copies,pa.stamp_name,pa.print_comment,pa.company_seal,pa.rep_seal, a.attachment_id FROM prj_project_attachment pa,sys_attachment a WHERE 1=1 AND cast(a.SOURCE_KEY as char(500))=cast(pa.project_id as char(500)) AND a.source_type = pa.project_attachment_category AND pa.project_attachment_category in ('FCT_CHANGE_PP')
AND pa.project_id = #{projectId}
AND pa.is_final_print = #{isFinalPrint}
) t1 LEFT JOIN sys_file sf ON sf.file_id = t1.file_id union select '保理上会审批通知书' document_name, sf.file_id, sf.file_name, sf.file_type, sf.file_suffix, sf.upload_date, sf.file_size, sf.last_updated_by as upload_person_id, sf.file_path, (SELECT su.description FROM sys_user su WHERE su.user_id = sf.last_updated_by) uploadPerson from SYS_FILE sf, SYS_ATTACHMENT sa where sa.SOURCE_TYPE = 'FCT_APPROVAL_NOTICE_REPORT' and sa.ATTACHMENT_ID = sf.ATTACHMENT_ID and sa.SOURCE_KEY in (select fc.project_id from fct_contract fc where fc.contract_id =#{projectId} and fc.data_class = 'CHANGE_REQ') union select 'HAND' document_name, sf.file_id, sf.file_name, sf.file_type, sf.file_suffix, sf.upload_date, sf.file_size, sf.last_updated_by as upload_person_id, sf.file_path, (SELECT su.description FROM sys_user su WHERE su.user_id = sf.last_updated_by) uploadPerson
from SYS_FILE sf, SYS_ATTACHMENT sa where sa.SOURCE_TYPE = 'FCT_APPROVAL_NOTICE_REPORT_H' and sa.ATTACHMENT_ID = sf.ATTACHMENT_ID and sa.SOURCE_KEY in (select fc.project_id from fct_contract fc where fc.contract_id =#{projectId} and fc.data_class = 'CHANGE_REQ')) tab order by tab.upload_date

select p.* from prj_project_attachment p
where p.project_attachment_category=#{projectAttachmentCategory} and
p.project_id=#{projectId}

select ppa.project_attachment_id, ppa.project_id, ppa.project_attachment_category, ppa.document_name, ppa.description, ppa.signed_date, ppa.contract_number, (select nvl(count(faa.attachment_id), 0) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = to_char(ppa.project_attachment_id) and faa.source_pk_value = faam.record_id) attachment_sum, (select max(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = to_char(ppa.project_attachment_id) and faa.source_pk_value = faam.record_id) attachment_id, (select wm_concat(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = to_char(ppa.project_attachment_id) and faa.source_pk_value = faam.record_id) attachment_id_n, (select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = to_char(ppa.project_attachment_id)) file_name, (select max(fat.last_update_date) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = to_char(ppa.project_attachment_id)) upload_date, (select max(su.description) from sys_user su, fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PRJ_PROJECT_ATTACHMENT' and faam.table_pk_value = to_char(ppa.project_attachment_id) and su.user_id = fat.last_updated_by) upload_person
from prj_project_attachment ppa where ppa.project_attachment_category IN ('CON_SIGN_ATT', 'HLS_PRJ_PROJECT_DOCX3') and ppa.prj_project_type is null and ppa.project_id = #{projectId}
AND ppa.project_attachment_category != #{projectAttachmentCategory}

select
    ppa.*
from
prj_project_attachment ppa
where ppa.project_id = #{projectId}
and ppa.attachment_code = #{attachmentCode}

SELECT count(1)
FROM fnd_atm_attachment       faa,
     fnd_atm_attachment_multi faam,
     prj_project_attachment   ppa
WHERE faam.attachment_id = faa.attachment_id
  AND faam.table_pk_value = ppa.project_attachment_id
  AND faam.table_name = #{tableName}
  and ppa.project_id = #{projectId}
  and ppa.project_attachment_category = #{attachmentCategory}

      AND ppa.attachment_code = #{attachmentCode}
